import {config} from './config.js';
import {cars} from './cars.js';
const $=s=>document.querySelector(s);const tg=window.Telegram?.WebApp;let filter='all',view='catalog',selected=null;let favorites=[];try{favorites=JSON.parse(localStorage.getItem('formula-favorites')||'[]');if(!Array.isArray(favorites))favorites=[]}catch{}
const money=n=>new Intl.NumberFormat('uk-UA').format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){let list=cars.filter(c=>(filter==='all'||c.status===filter)&&(view!=='favorites'||favorites.includes(c.id))&&(c.name+' '+c.trim).toLowerCase().includes($('#search').value.trim().toLowerCase()));const sort=$('#sort').value;if(sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(sort==='year')list.sort((a,b)=>b.year-a.year);$('#count').textContent=String(list.length).padStart(2,'0');$('#fav-count').textContent=favorites.length;$('#grid').innerHTML=list.map(c=>`<article class="card"><div class="photo"><button class="photo-open" data-detail="${c.id}" aria-label="Переглянути ${c.name}"><img src="${c.images[0]}" alt="${c.name}, ${c.year} — фото з оголошення Formula" loading="lazy"></button><span class="badge ${c.status}">${c.status==='stock'?'У наявності · за оголошенням':'У дорозі з США'}</span><button class="heart ${favorites.includes(c.id)?'saved':''}" data-fav="${c.id}" aria-label="${favorites.includes(c.id)?'Прибрати з обраного':'Додати до обраного'} ${c.name}" aria-pressed="${favorites.includes(c.id)}">${favorites.includes(c.id)?'♥':'♡'}</button></div><div class="card-body"><div class="card-top"><h3>${c.name}</h3><span class="year">${c.year}</span></div><p class="trim">${c.trim}</p><div class="specs"><span>${c.mileage}</span><span>${c.engine}</span><span>${c.gear}</span></div><div class="card-bottom"><span class="price">${money(c.price)} <small>$</small></span><button class="detail-btn" data-detail="${c.id}">Детальніше ↗</button></div></div></article>`).join('')||`<div class="empty"><h3>${view==='favorites'&&!favorites.length?'Тут будуть улюблені авто':'Автомобілі не знайдено'}</h3><p>${view==='favorites'&&!favorites.length?'Натисни на серце в картці автомобіля.':'Спробуй іншу модель або зміни фільтр.'}</p><button class="secondary" id="reset">Показати всі авто</button></div>`;$('#reset')?.addEventListener('click',()=>{filter='all';$('#search').value='';setView('catalog');syncFilters()});}
function syncFilters(){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}
function setView(v){view=v;$('#catalog').hidden=v==='contacts';$('#contacts').hidden=v!=='contacts';$('#view-title').firstChild.textContent=v==='favorites'?'Обране ':'Каталог авто ';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false')});render();}
function openTelegram(url){if(tg?.initData)tg.openTelegramLink(url);else window.open(url,'_blank','noopener,noreferrer');}
function showDetail(id){selected=cars.find(c=>c.id===id);if(!selected)return;const c=selected;$('#detail-body').innerHTML=`<div class="gallery" tabindex="0" aria-label="Фото автомобіля, прокручуйте горизонтально">${c.images.map((s,i)=>`<img src="${s}" alt="${c.name} — фото ${i+1}">`).join('')}</div><div class="detail-content"><p class="gallery-hint">Гортайте фото → · ${c.images.length} фото</p><p class="eyebrow">${c.status==='road'?'У ДОРОЗІ З США':'У НАЯВНОСТІ ЗА ОГОЛОШЕННЯМ'}</p><h2 id="detail-title">${c.name}</h2><p class="trim">${c.trim} · ${c.year}</p><div class="price">${money(c.price)} <small>$</small></div><p class="hint">${c.priceNote}. Уточніть актуальність у менеджера.</p><dl class="facts">${[['Пробіг',c.mileage],['Двигун',c.engine],['Коробка',c.gear],['Привід',c.drive]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><button class="primary" id="enquire">${c.status==='road'?'Дізнатись про доставку':'Консультація / тест-драйв'} ↗</button><a class="secondary" href="${c.source}" target="_blank" rel="noopener">Оголошення в Telegram ↗</a><details><summary>Опис та комплектація з оголошення</summary><p class="description">${esc(c.description)}</p></details></div>`;$('#enquire').onclick=()=>{$('#detail').close();$('#request-car').textContent=`${c.name} · ${c.year} · ${money(c.price)} $`;$('#lead-status').textContent='';$('#request').showModal();tg?.BackButton?.show()};$('#detail').showModal();tg?.BackButton?.show();}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail)showDetail(Number(detail.dataset.detail));const fav=e.target.closest('[data-fav]');if(fav){const id=Number(fav.dataset.fav);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('formula-favorites',JSON.stringify(favorites))}catch{}render();if(tg?.isVersionAtLeast?.('6.1'))tg.HapticFeedback?.selectionChanged();}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;syncFilters();render()}const v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);window.scrollTo({top:0,behavior:'smooth'})}});
$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);$('.brand').onclick=e=>{e.preventDefault();setView('catalog')};document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))tg?.BackButton?.hide()})});
$('#lead-form').addEventListener('submit',e=>{e.preventDefault();if(!selected)return;const data=new FormData(e.target);const text=`Вітаю! Цікавить ${selected.name} ${selected.year}.\n${data.get('intent')}\nІм’я: ${data.get('name')}\nТелефон: ${data.get('phone')}\nОголошення: ${selected.source}`;if(config.testMode){$('#lead-status').textContent='Тестову заявку сформовано. Вона нікуди не надіслана.';return;}openTelegram('https://t.me/l_e_v_a_nv?text='+encodeURIComponent(text));$('#lead-status').textContent='Повідомлення підготовлено. Надішліть його в чаті Telegram. Якщо чат не відкрився, скористайтеся контактами салону.';});
if(tg?.initData){tg.ready();tg.expand();if(tg.isVersionAtLeast('6.1')){tg.setHeaderColor('#141618');tg.setBackgroundColor('#141618');tg.BackButton.onClick(()=>document.querySelector('dialog[open]')?.close())}}
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_formula_catalog',description:'Filter the visible Formula car catalog by model name. Does not contact the dealership.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>100)throw new Error('Invalid query');filter='all';$('#search').value=input.query;syncFilters();setView('catalog');return {cars:cars.filter(c=>(c.name+' '+c.trim).toLowerCase().includes(input.query.trim().toLowerCase())).map(c=>({name:c.name,year:c.year,price:c.price,source:c.source}))}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}

if(config.testMode){document.querySelectorAll('a[href="https://t.me/formula_auto_nv"]').forEach(a=>a.href='https://t.me/'+config.channelUsername);$('.location').firstChild.textContent='Тестовий канал ';$('.intro-side').innerHTML='<p>Тестова версія Formula<br>Без надсилання заявок менеджерам</p>';$('#contacts').innerHTML='<p class="eyebrow">FORMULA · ТЕСТОВИЙ РЕЖИМ</p><h2>Тестовий канал</h2><div class="contact-box"><p>Перевіряйте каталог, пошук та обране. Заявки в цій версії не надсилаються справжньому салону.</p><a class="primary" href="https://t.me/'+config.channelUsername+'" target="_blank" rel="noopener">Відкрити тестовий канал ↗</a></div>';$('#lead-form .primary').textContent='Сформувати тестову заявку';$('#lead-form .hint').textContent='Тестовий режим. Дані не надсилаються і не зберігаються.';$('.consent').lastChild.textContent='Розумію, що це тестова форма без надсилання заявки.';}
